 "content": "from collections import Counter


def transform(grid):
    """Color the background tail after a rightmost foreground run of length >= 3."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    width = len(grid[0])
    for r, row in enumerate(grid):
        end = width - 1
        while end >= 0 and row[end] == background:
            end -= 1
        if end < 0 or end == width - 1:
            continue
        color = row[end]
        start = end
        while start > 0 and row[start - 1] == color:
            start -= 1
        if end - start + 1 >= 3:
            for c in range(end + 1, width):
                out[r][c] = 1
    return out


